<section class="card"><h2>Prepare an ad draft</h2><p class="sub">Review the design, ad text, destination, and budget before publishing. Attach a photo or MP4 video to launch.</p><div class="notice">Saving a draft does not publish an ad or spend money.</div><form id="aiads-copy-form" method="post" action="<?= base_url('marketing/ai_ads/save_draft?screen=mobile'); ?>"><input type="hidden" name="<?= html_escape($csrfName); ?>" value="<?= html_escape($csrfHash); ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(20)); ?>"><label class="field">What do you want to advertise?<textarea id="aiads-prompt" name="prompt" rows="3" maxlength="3000" required placeholder="Describe the product, goal and audience"><?= html_escape($director_prefill['prompt']??''); ?></textarea></label><button class="btn" id="aiads-generate" type="button">Suggest headline and text</button> <span id="aiads-copy-status" class="muted" aria-live="polite"><?php if(!empty($director_prefill)): ?>AI video copy is ready. Review and edit before saving.<?php endif; ?></span><label class="field">Choose a product (optional)</label><label class="choice"><input type="radio" name="product_id" value="0" checked><span>No product selected</span></label><?php foreach($products as $product): ?><label class="choice"><input type="radio" name="product_id" value="<?= (int)$product['id']; ?>"><span><?= html_escape($product['item_name']); ?></span></label><?php endforeach; ?><label class="field">Location<input name="location_text" maxlength="190" placeholder="Lekki, Lagos"></label><label class="field">Daily budget (₦)<input type="number" name="daily_budget" min="0" max="100000000" step="500" placeholder="3000"></label><label class="field">Duration in days<input type="number" name="duration_days" min="1" max="365" value="30" required></label><label class="field">Attach a creative (optional)</label><label class="choice"><input type="radio" name="media_asset_id" value="0" <?= empty($generated_media_prefill)?'checked':''; ?>><span>Choose later</span></label><?php foreach(($media_assets??array()) as $asset): ?><label class="choice"><input type="radio" name="media_asset_id" value="<?= (int)$asset['id']; ?>" <?= (int)($generated_media_prefill??0)===(int)$asset['id']?'checked':''; ?>><span><?= html_escape($asset['file_name']); ?><?= (int)($generated_media_prefill??0)===(int)$asset['id']?' · newly created, review it above':''; ?></span></label><?php endforeach; ?><label class="field">Headline<input id="aiads-headline" name="headline" maxlength="255" required value="<?= html_escape($director_prefill['headline']??''); ?>"></label><label class="field">Ad text<textarea id="aiads-body" name="body" rows="4" maxlength="5000" required><?= html_escape($director_prefill['primary_text']??''); ?></textarea></label><label class="field">Where should customers go?</label><label class="choice"><input type="radio" name="destination_type" value="WEBSITE" checked><span>Website or product page · Sales</span></label><label class="choice"><input type="radio" name="destination_type" value="WHATSAPP"><span>WhatsApp · Messages</span></label><label class="field">Website conversion event (Meta Pixel required)</label><label class="choice"><input type="radio" name="conversion_event" value="PURCHASE" checked><span>Purchase</span></label><label class="choice"><input type="radio" name="conversion_event" value="ADD_TO_CART"><span>Add to cart</span></label><label class="choice"><input type="radio" name="conversion_event" value="INITIATED_CHECKOUT"><span>Begin checkout</span></label><label class="choice"><input type="radio" name="conversion_event" value="LEAD"><span>Lead</span></label><label class="choice"><input type="radio" name="conversion_event" value="VIEW_CONTENT"><span>View content</span></label><label class="field">Website or WhatsApp URL (required before publish)<input type="url" name="destination_url" placeholder="https://... or https://wa.me/234..."></label><button class="btn" type="submit">Save a