nfirm('Publish this ad on Meta? Total campaign budget: ₦<?= number_format($total/100,0); ?> for <?= $duration; ?> days. Meta bills your ad account directly.');"><input type="hidden" name="<?= html_escape($csrfName); ?>" value="<?= html_escape($csrfHash); ?>"><input type="hidden" name="campaign_id" value="<?= (int)$campaign['id']; ?>"><input type="hidden" name="confirmed_total_minor" value="<?= $total; ?>"><label class="choice"><input type="checkbox" name="approve_spend" value="1" required><span>I approve up to ₦<?= number_format($total/100,0); ?> total spend</span></label><button class="btn" type="submit" <?= empty($has_ads_access)||empty($connection['ad_account_id'])||empty($campaign['media_asset_id'])?'disabled':''; ?>>Publish ad</button></form><?php elseif($campaign['status']==='active'): ?><form method="post" action="<?= base_url('marketing/ai_ads/pause_campaign?screen=mobile'); ?>"><input type="hidden" name="<?= html_escape($csrfName); ?>" value="<?= html_escape($csrfHash); ?>"><input type="hidden" name="campaign_id" value="<?= (int)$campaign['id']; ?>"><button class="btn" type="submit">Pause ad</button></form><?php endif; ?><?php if(!empty($campaign['insights'])): $stats=$campaign['insights']; ?><p>Last 7 days: <?= number_format((int)($stats['impressions']??0)); ?> impressions · <?= number_format((int)($stats['clicks']??0)); ?> clicks · ₦<?= number_format((float)($stats['spend']??0),2); ?> spend</p><?php if(!empty($campaign['result_events'])): ?><p>Results attributed by Meta: <?= number_format((int)($campaign['result_events']['purchases']??0)); ?> purchases · <?= number_format((int)($campaign['result_events']['leads']??0)); ?> leads · <?= number_format((int)($campaign['result_events']['conversations']??0)); ?> conversations</p><?php endif; ?><?php endif; ?></article><?php endforeach; endif; ?></section>
</main><script>(function(){var mf=document.getElementById('aiads-media-form'),ms=document.getElementById('aiads-media-status');if(mf)mf.addEventListener('submit',function(e){e.preventDefault();var b=mf.querySelector('button[type=submit]');b.disabled=true;ms.textContent='Creating your creative… This may take a minute.';fetch(mf.action,{method:'POST',body:new FormData(mf),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'Could not create the creative.');window.location.reload()}).catch(function(e){ms.textContent=e.message||'Creative generation is unavailable.';b.disabled=false})});var uf=document.getElementById('aiads-upload-form'),us=document.getElementById('aiads-upload-status');if(uf)uf.addEventListener('submit',function(e){e.preventDefault();var b=uf.querySelector('button[type=submit]');b.disabled=true;us.textContent='Uploading…';fetch(uf.action,{method:'POST',body:new FormData(uf),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'Could not add media.');window.location.reload()}).catch(function(e){us.textContent=e.message||'Upload failed.';b.disabled=false})})})();(function(){var b=document.getElementById('aiads-generate'),s=document.getElementById('aiads-copy-status');if(!b)return;b.addEventListener('click',function(){var p=document.getElementById('aiads-prompt').value.trim();if(!p){s.textContent='Describe your ad first.';return}b.disabled=true;s.textContent='Generating…';var d=new URLSearchParams();d.append('<?= html_escape($csrfName); ?>','<?= html_escape($csrfHash); ?>');d.append('prompt',p);d.append('product_id',(document.querySelector('input[name=product_id]:checked')||{}).value||'0');fetch('<?= base_url('marketing/ai_ads/generate_copy'); ?>',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},credentials:'same-origin',body:d.toString()}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'AI copy is unavailable.');document.getElementById('aiads-headline').value=r.copy.headline;document.getElementById('aiads-body').value=r.copy.body;s.textContent='Review and edit before saving.'+(r.usage?' ('+r.usage.used+' of '+r.usage.limit+' used this plan month).':'')}).catch(function(e){s.textContent=e.message||'AI copy unavailable.'}).finally(function(){b.disabled=false})})})();</script><?php $this->load->view('mobile/bottom_nav',array('active'=>'more')); ?><?php $this->load->view('mobile/chat'); ?></body></html>
